import{_ as a,o,c as s,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Inscription","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/inscription.md","filePath":"es/guide/professions/inscription.md"}'),r={name:"es/guide/professions/inscription.md"};function n(t,e,c,d,l,p){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="inscription" tabindex="-1">Inscription <a class="header-anchor" href="#inscription" aria-label="Enlace permanente a &quot;Inscription&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> <strong>Implementación:</strong> no se ha establecido que este rediseño esté implementado. <strong>Disponibilidad:</strong> no se ha establecido que esté disponible en juego. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-09 respecto al Batch 04.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Inscription registra, conserva y modifica el conocimiento mágico.</li><li>Pergaminos, variantes y grimorios organizados aportan funciones tácticas y económicas.</li><li>Ejecución, métodos aprendidos y especialización son distintos; los productos mágicos físicos conservan el riesgo de saqueo.</li></ul><p><a href="/Syrolands-Public/es/game-design/professions/inscription.html">Especificación completa del diseño</a></p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Función / límite Propuesto</th></tr></thead><tbody><tr><td>Qué hace</td><td>Inscription se propone como ingeniería mágica: registrar, conservar y cambiar cuidadosamente estructuras mágicas escritas. Los pergaminos son uno de sus productos; glifos, notación de variantes, grimorios indexados, protecciones y diagramas rituales son otras especializaciones candidatas.</td></tr><tr><td>Habilidad e identidad</td><td>La habilidad permite la ejecución, las técnicas/escuelas aprendidas aportan métodos y las vías profesionales expresan especialización. Un escriba podría hacerse conocido por pergaminos de combate, variantes raras o libros bien organizados. Los nombres de las técnicas y el alcance de las protecciones/rituales no son definitivos.</td></tr><tr><td>Aprendizaje y producción</td><td>Magery, los patrones conocidos, los reactivos y Alchemy pueden interactuar con el oficio. Comprar un pergamino de lanzamiento ordinario no compraría conocimiento permanente; copiar y enseñar entre jugadores necesitan reglas explícitas. Secretos, producción, encargos y reputación siguen la <a href="/Syrolands-Public/es/guide/professions/overview.html">propuesta compartida de profesiones</a>.</td></tr><tr><td>Valor táctico y riesgo</td><td>Los pergaminos preparados pueden ofrecer una consulta de emergencia más rápida a un coste consumible. Los grimorios físicos raros y los reactivos siguen expuestos al riesgo de saqueo; la elaboración no otorga seguro. <a href="/Syrolands-Public/es/guide/magic/spellbooks-scrolls-and-reagents.html">Libros y materiales</a> · <a href="/Syrolands-Public/es/guide/magic/variants-and-glyphs.html">Variantes</a>.</td></tr></tbody></table>',7)])])}const g=a(r,[["render",n]]);export{m as __pageData,g as default};
